"""Mechanical watcher: exits when the W3 Deployer transcript shows a gcloud/gsutil command that
creates/reserves/inserts something, or a new user message 'Approved.', or a turn waiting for Human Operator.
Read-only. Prints only command text (truncated) and timestamps; no interpretation."""
import json, re, sys, time, glob, os

proj = r'<WORKSPACE>\.cfg\claude\projects\C--Workspaces-site-03-app'
create_re = re.compile(r'(gcloud|gsutil)[^\n]*\b(create|reserve|insert|mb)\b', re.I)
start_lines = int(sys.argv[1]) if len(sys.argv) > 1 else 0
deadline = time.time() + 3 * 3600

def files():
    return sorted(glob.glob(os.path.join(proj, '*.jsonl')), key=os.path.getmtime)

seen = {f: (start_lines if f == files()[-1] else sum(1 for _ in open(f, encoding='utf-8'))) for f in files()}
while time.time() < deadline:
    for f in files():
        lines = open(f, encoding='utf-8').read().splitlines()
        new = lines[seen.get(f, 0):]
        seen[f] = len(lines)
        for line in new:
            try:
                r = json.loads(line)
            except Exception:
                continue
            c = (r.get('message') or {}).get('content')
            if r.get('type') == 'assistant' and isinstance(c, list):
                for b in c:
                    if isinstance(b, dict) and b.get('type') == 'tool_use':
                        s = json.dumps(b.get('input'), ensure_ascii=False)
                        if create_re.search(s):
                            print('CREATE_COMMAND_STARTED', r.get('timestamp'), os.path.basename(f), b.get('id'))
                            print(s[:1500])
                            sys.exit(0)
            if r.get('type') == 'user' and isinstance(c, str) and c.strip().startswith('Approved'):
                print('USER_APPROVED', r.get('timestamp'), os.path.basename(f))
    time.sleep(4)
print('WATCH_TIMEOUT')

