"""W3 custody secret scan. Prints file / category / count only — never values.
Optional --redact OUTDIR writes redacted copies replacing matched values with [REDACTED:<category>]."""
import os, re, sys, json, hashlib

PATTERNS = {
    'gcp_access_token': re.compile(r'ya29\.[0-9A-Za-z_\-\.]{20,}'),
    'github_token': re.compile(r'\b(gh[pousr]_[A-Za-z0-9]{30,}|github_pat_[A-Za-z0-9_]{30,})'),
    'google_api_key': re.compile(r'AIza[0-9A-Za-z_\-]{35}'),
    'private_key_block': re.compile(r'-----BEGIN [A-Z ]*PRIVATE KEY-----[\s\S]{0,4000}?-----END [A-Z ]*PRIVATE KEY-----'),
    'bearer_header': re.compile(r'(?i)(authorization\s*[:=]\s*\\?"?bearer\s+)([A-Za-z0-9_\-\.=]{16,})'),
    'assigned_secret': re.compile(r'(?i)((?:password|passwd|passphrase|secret[_-]?key|secret|token|api[_-]?key|_key)\s*[=:]\s*\\?["\']?)([A-Za-z0-9/+_\-\.=!@#$%^&*]{12,})'),
    'jwt': re.compile(r'\beyJ[A-Za-z0-9_\-]{10,}\.eyJ[A-Za-z0-9_\-]{10,}\.[A-Za-z0-9_\-]{10,}'),
    'ssh_pubkey_material': re.compile(r'ssh-(?:ed25519|rsa) AAAA[0-9A-Za-z+/=]{40,}'),
}
# benign value shapes for assigned_secret (placeholders / variable refs)
BENIGN = re.compile(r'^(\$|\{|<|\[REDACTED|x{6,}|\*{4,}|changeme|example|placeholder|none|null|true|false)', re.I)

def iter_files(roots):
    for root in roots:
        if os.path.isfile(root):
            yield root; continue
        for dp, dn, fn in os.walk(root):
            if os.sep + 'src' in dp.replace('/', os.sep) and 'site-03' in dp:  # skip upstream source clones
                continue
            for f in fn:
                yield os.path.join(dp, f)

def scan(text):
    hits = {}
    for cat, rx in PATTERNS.items():
        for m in rx.finditer(text):
            val = m.group(2) if cat in ('bearer_header', 'assigned_secret') else m.group(0)
            if cat == 'assigned_secret' and BENIGN.match(val):
                continue
            hits.setdefault(cat, []).append((m.start(), m.end(), val))
    return hits

def main():
    args = sys.argv[1:]
    outdir = None
    if '--redact' in args:
        i = args.index('--redact'); outdir = args[i + 1]; args = args[:i] + args[i + 2:]
    canary = 'password=<CREDENTIAL_VALUE_REMOVED>'
    assert 'assigned_secret' in scan(canary), 'canary not detected'
    print('canary: detected')
    total = 0
    for f in iter_files(args):
        try:
            t = open(f, encoding='utf-8', errors='replace').read()
        except Exception:
            continue
        h = scan(t)
        if h:
            n = sum(len(v) for v in h.values()); total += n
            print(f"{f} :: " + ', '.join(f'{k}={len(v)}' for k, v in sorted(h.items())))
        if outdir:
            red = t
            vals = sorted({v for lst in h.values() for (_, _, v) in lst}, key=len, reverse=True)
            cats = {v: k for k, lst in h.items() for (_, _, v) in lst}
            for v in vals:
                red = red.replace(v, f'[REDACTED:{cats[v]}]')
            rel = os.path.relpath(f, os.path.commonpath(args) if len(args) > 1 else os.path.dirname(args[0]))
            dst = os.path.join(outdir, rel); os.makedirs(os.path.dirname(dst), exist_ok=True)
            open(dst, 'w', encoding='utf-8', newline='').write(red)
    print('total candidate hits:', total)

main()

